 const f=mediaHarness();await f.update(roomState());await f.click('mediaConsentAccept');f.players[0].ready();const watcher=f.observers.find(observer=>observer.target===f.players[0].iframe);watcher.emit([{intersectionRatio:.5}]);assert.equal(f.players[0].destroyed,true);
