test('playlist close and Escape leave the side-by-side video player and timeline intact and restore focus',async()=>{
 const f=mediaHarness();f.window.innerWidth=1794;f.window.innerHeight=1109;f.node('mediaPlayer').rect={left:950,top:170,width:800,height:500};await f.update(roomState());await f.click('mediaConsentAccept');const player=f.players[0];player.ready();await f.flushFrames();const iframe=player.iframe,calls=player.calls.length;await f.openPlaylist();assert.equal(f.node('tableMediaPlaylist').open,true);assert.equal(f.node('tableMedia').open,true);assert.equal(player.destroyed,false);assert.equal(player.iframe,iframe);assert.equal(player.calls.length,calls);
 const left=f.node('tableMediaPlaylist').getBoundingClientRect();assert.ok(left.right<=950);f.document.dispatch('keydown',{key:'Escape',preventDefault(){}});assert.equal(f.node('tableMediaPlaylist').open,false);assert.equal(f.node('tableMedia').open,true);assert.equal(f.document.activeElement,f.node('mediaPlaylistOpen'));assert.equal(player.destroyed,false);assert.equal(posts(f).length,0);await f.openPlaylist();await f.click('mediaPlaylistClose');assert.equal(player.iframe,iframe);assert.equal(player.calls.length,calls);
});

test('playlist height follows content with a viewport cap; enlarging the player has no former 360px video cap',async()=>{
 const f=mediaHarness();f.window.innerWidth=2000;f.window.innerHeight=1400;await f.update(roomState());await f.click('mediaConsentDecline');await f.open();f.node('mediaPlaylistBody').scrollHeight=180;await f.openPlaylist();assert.ok(f.node('tableMediaPlaylist').getBoundingClientRect().height<560);await f.click('mediaPlaylistClose');f.node('mediaPlaylistBody').scrollHeight=2000;await f.openPlaylist();assert.equal(f.node('tableMediaPlaylist').getBoundingClientRect().height,560);await f.click('mediaPlaylistClose');const edge=f.node('tableMedia').querySelector('.media-resize-n');for(let i=0;i<14;i++)edge.onkeydown({key:'ArrowUp',shiftKey:true,preventDefault(){}});await f.flushFrames();assert.ok(parseFloat(f.node('tableMedia').style.getPropertyValue('--media-player-height'))>360);assert.equal(posts(f).length,0);
});

test('playlist shows enqueue errors and stale feedback and cleans its own gestures on close or room change',async()=>{
 const initial=mediaSnapshot({queue:[queued('a'),queued('b')]}),f=mediaHarness({fetchHandler:request=>request.route==='/api/music'?json({tracks:[]}):request.body?json({error:'不能點播'},{ok:false,status:403}):json(initial)});await f.update(roomState(initial));await f.click('mediaConsentDecline');await f.open();await f.openPlaylist();f.node('mediaUrl').value='https://youtu.be/M7lc1UVf-VE';await f.submit('mediaVideoForm');assert.match(f.node('mediaPlaylistStatus').textContent,/不能點播/);assert.equal(f.node('mediaPlaylistStatus').getAttribute('aria-live'),'polite');const bar=f.node('mediaPlaylistBar');bar.onpointerdown(pointer(1,100,100,{target:bar,isPrimary:true}));assert.equal(bar.hasPointerCapture(1),true);await f.click('mediaPlaylistClose');assert.equal(bar.hasPointerCapture(1),false);assert.equal(f.node('tableMedia').open,true);
 await f.openPlaylist();const handle=f.node('mediaQueue').children[1].querySelector('.table-media-drag-handle');handle.onpointerdown(pointer(2,50,100,{isPrimary:true}));f.window.TableMedia.stop();assert.equal(handle.hasPointerCapture(2),false);assert.equal(f.node('tableMediaPlaylist').open,false);assert.equal(f.node('tableMedia').open,false);
});

test('an overlapping narrow playlist retires only local video and closing it does not automatically remount or stop the room',async()=>{
 const f=mediaHarness();f.window.innerWidth=390;f.window.innerHeight=500;f.node('mediaPlayer').rect={left:20,top:80,width:350,height:400};await f.update(roomState());await f.click('mediaConsentAccept');assert.equal(f.players.length,1);await f.openPlaylist();assert.equal(f.players[0].destroyed,true);assert.equal(f.node('tableMedia').open,true);assert.equal(f.node('tableMediaPlaylist').open,true);assert.match(f.node('mediaPlaybackStatus').textContent,/清單.*重新加入/);assert.equal(f.node('mediaCurrentTitle').textContent,'影片A');await f.click('mediaPlaylistClose');assert.equal(f.players.length,1);assert.equal(posts(f).length,0);await f.click('mediaVideoJoin');assert.equal(f.players.length,2);
});

test('global and device playback use distinct icons and names while device play preserves shared permissions',async()=>{
 const guest=mediaSnapshot({current:music(),myPlayerId:'guest',isHost:false,canControl:false,canManageQueue:false,playback:{state:'playing',anchorPositionSec:0,anchorServerMs:100000,rate:1}}),{f}=mutable(guest);await f.update(roomState(guest));await f.click('mediaConsentDecline');await f.open();assert.equal(f.node('mediaPlay').dataset.uiIcon,'play');assert.equal(f.node('mediaPlay').title,'全桌播放');assert.equal(f.node('mediaResume').dataset.uiIcon,'playLocal');assert.equal(f.node('mediaResume').title,'在自己的裝置播放');assert.equal(f.node('mediaResume').getAttribute('aria-label'),'在自己的裝置播放');assert.equal(f.node('mediaPlay').disabled,true);assert.equal(f.node('mediaResume').disabled,false);
 await f.click('mediaResume');assert.equal(posts(f).length,0);assert.equal(f.audioClips[0].paused,false);assert.equal(f.node('mediaPlay').disabled,true);assert.equal(f.node('mediaResume').dataset.iconOnly,'true');
 const host=mutable(mediaSnapshot({current:music()})).f;await host.update(roomState());await host.click('mediaConsentDecline');await host.open();await host.click('mediaPlay');assert.equal(posts(host)[0].body.action,'play');assert.equal(host.node('mediaResume').dataset.uiIcon,'playLocal');
});

test('one responsive control row contains distinct global and personal groups, full volume and the right queue entry',async()=>{
 const f=mediaHarness();await f.update(roomState());await f.click('mediaConsentDecline');await f.open();const row=f.node('mediaControlRow');assert.deepEqual(row.children.map(node=>node.id),['mediaTransport','mediaLocalControls','mediaPlaylistEntry']);assert.equal(f.node('mediaTransport').getAttribute('role'),'group');assert.equal(f.node('mediaTransport').getAttribute('aria-label'),'全桌播放控制');assert.equal(f.node('mediaLocalControls').getAttribute('role'),'group');assert.equal(f.node('mediaLocalControls').getAttribute('aria-label'),'自己的裝置播放控制');assert.equal(row.contains(f.node('mediaVolume')),true);assert.equal(row.contains(f.node('mediaPlaylistOpen')),true);assert.equal(row.contains(f.node('mediaSeek')),false);
 const css=require('node:fs').readFileSync(require('node:path').join(__dirname,'../public/shared/table-media.css'),'utf8');assert.match(css,/\.table-media-control-row\{display:flex;align-items:center;flex-wrap:wrap/);assert.match(css,/\.table-media-local\{[^}]*border-left:1px/);assert.doesNotMatch(css,/\.table-media-local\{[^}]*border-top/);assert.match(css,/\.table-media-local input\{width:120px;min-width:120px;flex:none/);assert.match(css,/\.table-media-playlist-entry\{[^}]*margin-left:auto/);
});
